/// Initialise the encrypted BetTotals PDA for a private market.
/// Creator pays; queues the `init_private_market_state` MPC circuit.
/// `nonce` is a random u128 that seeds the initial MXE ciphertext.
pub fn init_private_market_state(
    ctx: Context<InitPrivateMarketState>,
    computation_offset: u64,
    nonce: u128,
) -> Result<()> {
    require!(ctx.accounts.market.is_private, TerracError::MarketNotPrivate);
    require!(ctx.accounts.market.status == MarketStatus::Open, TerracError::MarketNotOpen);

    let state = &mut ctx.accounts.private_state;
    state.market = ctx.accounts.market.key();
    state.bump = ctx.bumps.private_state;
    // no_total_nonce / yes_total_nonce get written by the init callback;
    // the input `nonce` seeds the MXE encryption inside the circuit.

    let args = ArgBuilder::new()
        .plaintext_u128(nonce)
        .build();

    queue_computation(
        ctx.accounts,
        computation_offset,
        args,
        vec![crate::InitPrivateMarketStateV8Callback::callback_ix(
            computation_offset,
            &ctx.accounts.mxe_account,
            &[CallbackAccount {
                pubkey: ctx.accounts.private_state.key(),
                is_writable: true,
            }],
        )?],
        1,
        0,
    )?;

    Ok(())
}

pub fn init_private_market_state_callback(
    ctx: Context<crate::InitPrivateMarketStateV8Callback>,
    output: SignedComputationOutputs<InitPrivateMarketStateV8Output>,
) -> Result<()> {
    let o = match output.verify_output(
        &ctx.accounts.cluster_account,
        &ctx.accounts.computation_account,
    ) {
        Ok(o) => o,
        Err(_) => return Err(TerracError::AbortedComputation.into()),
    };

    // Circuit returns (Enc<Mxe, u64>, Enc<Mxe, u64>) — both initialized to 0.
    // o.field_0.field_0 = no_total, o.field_0.field_1 = yes_total.
    let state = &mut ctx.accounts.private_state;
    state.no_total_ct = o.field_0.field_0.ciphertexts[0];
    state.no_total_nonce = o.field_0.field_0.nonce;
    state.yes_total_ct = o.field_0.field_1.ciphertexts[0];
    state.yes_total_nonce = o.field_0.field_1.nonce;
    Ok(())
}

/// Place an encrypted bet on a private market.
/// Bettor encrypts ONLY `outcome` (u64, value 0 or 1) under a Shared session.
/// `amount` is a plaintext u64 — already public via the USDC transfer.
/// `outcome_commitment` = blake3(outcome_byte || secret_32_bytes) — binds the
/// bettor's side for the public claim-winnings path.
pub fn place_private_bet(
    ctx: Context<PlacePrivateBet>,
    computation_offset: u64,
    outcome_ct: [u8; 32],
    encryption_pubkey: [u8; 32],
    bet_nonce: u128,
    amount: u64,
    outcome_commitment: [u8; 32],
) -> Result<()> {
    require!(amount >= MIN_BET, TerracError::BetTooSmall);
    let market = &ctx.accounts.market;
    require!(market.is_private, TerracError::MarketNotPrivate);
    require!(market.status == MarketStatus::Open, TerracError::MarketNotOpen);
    require!(
        Clock::get()?.unix_timestamp < market.expiry,
        TerracError::MarketExpired
    );
    require!(!ctx.accounts.private_state.is_revealed, TerracError::AlreadyRevealed);

    // Transfer USDC: bettor ATA → market vault (amount is public)
    token::transfer(
        CpiContext::new(
            ctx.accounts.token_program.to_account_info(),
            Transfer {
                from: ctx.accounts.bettor_ata.to_account_info(),
                to: ctx.accounts.vault.to_account_info(),
                authority: ctx.accounts.bettor.to_account_info(),
            },
        ),
        amount,
    )?;

    let record = &mut ctx.accounts.private_bet_record;
    record.market = market.key();
    record.bettor = ctx.accounts.bettor.key();
    record.amount = amount;
    record.outcome_commitment = outcome_commitment;
    record.outcome_ct = outcome_ct;
    record.amount_ct = [0u8; 32];           // legacy field, unused in u64-only flow
    record.encryption_pubkey = encryption_pubkey;
    record.bet_nonce = bet_nonce;
    record.claimed = false;
    record.bump = ctx.bumps.private_bet_record;

    let no_nonce = ctx.accounts.private_state.no_total_nonce;
    let yes_nonce = ctx.accounts.private_state.yes_total_nonce;
    // Fresh nonce for the Mxe-sealed outcome encryption.
    let seal_nonce: u128 = ((computation_offset as u128) << 64) | 0xA12C1_5EA1_u128;

    let args = ArgBuilder::new()
        // Enc<Shared, u64> outcome — single ciphertext
        .x25519_pubkey(encryption_pubkey)
        .plaintext_u128(bet_nonce)
        .encrypted_u64(outcome_ct)
        // public u64 amount
        .plaintext_u64(amount)
        // Enc<Mxe, u64> no_total — at byte offset NO_TOTAL_OFFSET
        .plaintext_u128(no_nonce)
        .account(
            ctx.accounts.private_state.key(),
            NO_TOTAL_OFFSET,
            TOTAL_SIZE,
        )
        // Enc<Mxe, u64> yes_total — at byte offset YES_TOTAL_OFFSET
        .plaintext_u128(yes_nonce)
        .account(
            ctx.accounts.private_state.key(),
            YES_TOTAL_OFFSET,
            TOTAL_SIZE,
        )
        // seal_mxe: Mxe — nonce only (Mxe handle is injected by Arcium)
        .plaintext_u128(seal_nonce)
        .build();

    queue_computation(
        ctx.accounts,
        computation_offset,
        args,
        vec![crate::PlacePrivateBetV8Callback::callback_ix(
            computation_offset,
            &ctx.accounts.mxe_account,
            &[
                CallbackAccount {
                    pubkey: ctx.accounts.private_state.key(),
                    is_writable: true,
                },
                CallbackAccount {
                    pubkey: ctx.accounts.private_bet_record.key(),
                    is_writable: true,
                },
            ],
        )?],
        1,
        0,
    )?;

    emit!(PrivateBetPlaced {
        market: market.key(),
        bettor: ctx.accounts.bettor.key(),
        amount,
    });

    Ok(())
}

pub fn place_private_bet_callback(
    ctx: Context<crate::PlacePrivateBetV8Callback>,
    output: SignedComputationOutputs<PlacePrivateBetV8Output>,
) -> Result<()> {
    let o = match output.verify_output(
        &ctx.accounts.cluster_account,
        &ctx.accounts.computation_account,
    ) {
        Ok(o) => o,
        Err(e) => {
            msg!("place_private_bet_callback verify_output error: {:?}", e);
            return Err(e);
        }
    };

    // Circuit returns (Enc<Mxe, u64>, Enc<Mxe, u64>, Enc<Mxe, u64>):
    //   field_0.field_0 = new no_total
    //   field_0.field_1 = new yes_total
    //   field_0.field_2 = sealed outcome
    let state = &mut ctx.accounts.private_state;
    state.no_total_ct = o.field_0.field_0.ciphertexts[0];
    state.no_total_nonce = o.field_0.field_0.nonce;
    state.yes_total_ct = o.field_0.field_1.ciphertexts[0];
    state.yes_total_nonce = o.field_0.field_1.nonce;

    let record = &mut ctx.accounts.private_bet_record;
    record.mxe_outcome_ct = o.field_0.field_2.ciphertexts[0];
    record.mxe_outcome_nonce = o.field_0.field_2.nonce;
    record.mxe_outcome_sealed = true;
    Ok(())
}

/// Reveal the encrypted bet totals and settle the market in one atomic callback.
/// Only the market creator can trigger the reveal (signer check in accounts struct).
pub fn reveal_private_market(
    ctx: Context<RevealPrivateMarket>,
    computation_offset: u64,
) -> Result<()> {
    require!(ctx.accounts.market.is_private, TerracError::MarketNotPrivate);
    require!(ctx.accounts.market.status == MarketStatus::Open, TerracError::MarketNotOpen);
    require!(!ctx.accounts.private_state.is_revealed, TerracError::AlreadyRevealed);

    let no_nonce = ctx.accounts.private_state.no_total_nonce;
    let yes_nonce = ctx.accounts.private_state.yes_total_nonce;
    let args = ArgBuilder::new()
        // Enc<Mxe, u64> no_total
        .plaintext_u128(no_nonce)
        .account(
            ctx.accounts.private_state.key(),
            NO_TOTAL_OFFSET,
            TOTAL_SIZE,
        )
        // Enc<Mxe, u64> yes_total
        .plaintext_u128(yes_nonce)
        .account(
            ctx.accounts.private_state.key(),
            YES_TOTAL_OFFSET,
            TOTAL_SIZE,
        )
        .build();

    queue_computation(
        ctx.accounts,
        computation_offset,
        args,
        vec![crate::RevealPrivateMarketV8Callback::callback_ix(
            computation_offset,
            &ctx.accounts.mxe_account,
            &[
                CallbackAccount {
                    pubkey: ctx.accounts.private_state.key(),
                    is_writable: true,
                },
                CallbackAccount {
                    pubkey: ctx.accounts.market.key(),
                    is_writable: true,
                },
            ],
        )?],
        1,
        0,
    )?;

    Ok(())
}

pub fn reveal_private_market_callback(
    ctx: Context<crate::RevealPrivateMarketV8Callback>,
    output: SignedComputationOutputs<RevealPrivateMarketV8Output>,
) -> Result<()> {
    let o = match output.verify_output(
        &ctx.accounts.cluster_account,
        &ctx.accounts.computation_account,
    ) {
        Ok(o) => o,
        Err(_) => return Err(TerracError::AbortedComputation.into()),
    };

    // reveal_private_market_v8 returns Totals { no, yes } as a struct.
    // Output type: RevealPrivateMarketV8Output { field_0: Struct { field_0: u64, field_1: u64 } }
    // where field_0 = no, field_1 = yes (matches struct declaration order).
    let no_vol = o.field_0.field_0;
    let yes_vol = o.field_0.field_1;

    let state = &mut ctx.accounts.private_state;
    state.no_volume_revealed = no_vol;
    state.yes_volume_revealed = yes_vol;
    state.is_revealed = true;

    let market = &mut ctx.accounts.market;
    market.no_volume = no_vol;
    market.yes_volume = yes_vol;
    market.total_volume = no_vol.saturating_add(yes_vol);

    // NOTE: market.outcome / market.status are intentionally NOT set here.
    // The (u64, u64) tuple reveal on this MXE cluster produces garbage volumes,
    // so auto-settling from them would be random. The creator must call
    // settle_market(winning_outcome) after this reveal to make settlement explicit.
    // Until the cluster's tuple-output bug is fixed, this is the safe behavior.

    emit!(PrivateMarketRevealed {
        market: market.key(),
        yes_volume: yes_vol,
        no_volume: no_vol,
        winning_outcome: 0, // sentinel — actual settlement happens in settle_market
    });

    Ok(())
}

/// Claim winnings from a settled private market.
/// The bettor reveals their `outcome` and the `secret` used in the commitment.
/// Program verifies: blake3(outcome || secret) == stored commitment.
pub fn claim_private_winnings(
    ctx: Context<ClaimPrivateWinnings>,
    outcome: u8,
    secret: [u8; 32],
) -> Result<()> {
    let market = &ctx.accounts.market;
    let state = &ctx.accounts.private_state;
    let record = &mut ctx.accounts.private_bet_record;

    require!(market.status == MarketStatus::Settled, TerracError::MarketNotSettled);
    require!(state.is_revealed, TerracError::NotYetRevealed);
    require!(!record.claimed, TerracError::AlreadyClaimed);

    // Verify commitment: only the bettor who placed the bet knows their secret.
    let mut preimage = Vec::with_capacity(33);
    preimage.push(outcome);
    preimage.extend_from_slice(&secret);
    let commitment: [u8; 32] = blake3::hash(&preimage).into();
    require!(commitment == record.outcome_commitment, TerracError::InvalidCommitment);

    let winning_outcome = market.outcome.ok_or(TerracError::MarketNotSettled)?;
    require!(outcome == winning_outcome, TerracError::BetDidNotWin);

    let winning_vol = if winning_outcome == 1 {
        state.yes_volume_revealed
    } else {
        state.no_volume_revealed
    };
    require!(winning_vol > 0, TerracError::ZeroWinningVolume);

    let gross_payout = (record.amount as u128)
        .checked_mul(market.total_volume as u128)
        .ok_or(TerracError::Overflow)?
        .checked_div(winning_vol as u128)
        .ok_or(TerracError::Overflow)? as u64;

    let fee = (gross_payout as u128)
        .checked_mul(market.creator_fee_bps as u128)
        .ok_or(TerracError::Overflow)?
        .checked_div(10_000)
        .ok_or(TerracError::Overflow)? as u64;
    let net_payout = gross_payout.checked_sub(fee).ok_or(TerracError::Overflow)?;

    let (creator, nonce_le, market_bump) = (
        market.creator,
        market.nonce.to_le_bytes(),
        market.bump,
    );
    let signer_seeds: &[&[&[u8]]] =
        &[&[b"market", creator.as_ref(), &nonce_le, &[market_bump]]];

    token::transfer(
        CpiContext::new_with_signer(
            ctx.accounts.token_program.to_account_info(),
            Transfer {
                from: ctx.accounts.vault.to_account_info(),
                to: ctx.accounts.bettor_ata.to_account_info(),
                authority: ctx.accounts.market.to_account_info(),
            },
            signer_seeds,
        ),
        net_payout,
    )?;

    if fee > 0 {
        token::transfer(
            CpiContext::new_with_signer(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.vault.to_account_info(),
                    to: ctx.accounts.creator_ata.to_account_info(),
                    authority: ctx.accounts.market.to_account_info(),
                },
                signer_seeds,
            ),
            fee,
        )?;
    }

    record.claimed = true;

    emit!(PrivateWinningsClaimed {
        market: market.key(),
        bettor: ctx.accounts.bettor.key(),
        payout: net_payout,
    });

    Ok(())
}
